import {createIcons,icons} from 'lucide';
import {today,initial,integer,cents,sale,units,paid,debt,routeStats,validateVisit,allocate,validateDB,PRODUCTS,ALL_PRODUCTS,productName,typeMap,typeTotal,routeTypes,visitTypes,validateLocation,mapsURL,routeDeletionInfo,deleteRoute} from './domain.mjs';
import {makeExcel} from './report.mjs';
import {showMap} from './maps.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(v/100);
const dateLabel=d=>new Intl.DateTimeFormat('es-EC',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const time=v=>new Intl.DateTimeFormat('es-EC',{hour:'2-digit',minute:'2-digit',timeZone:'America/Guayaquil'}).format(new Date(v));
const id=()=>crypto.randomUUID();const now=()=>new Date().toISOString();const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
let db,conn,view='home',shopQuery='',reports={start:today(),end:today()},modalPhotos=[],installPrompt=null,busy=false,modalReturn=null,modalLocation=null,mapDate= today();
const active=()=>db.routes.find(r=>!r.closed);const lastRoute=()=>active()||[...db.routes].sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0];
const shopName=v=>v.shopName||db.shops.find(s=>s.id===v.shopId)?.name||'Tienda';
function toast(message,bad=false){const t=$('#toast');t.textContent=message;t.className=bad?'show bad':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4500);}
function navTo(v){view=v;render();window.scrollTo({top:0});}
async function readData(){return new Promise((resolve,reject)=>{const t=conn.transaction('data','readonly');const r=t.objectStore('data').get('main');r.onsuccess=()=>resolve(r.result||initial());r.onerror=()=>reject(r.error);});}
async function commit(change){if(busy)throw Error('Espera un momento antes de guardar de nuevo.');busy=true;try{let next;await new Promise((resolve,reject)=>{const t=conn.transaction('data','readwrite');const store=t.objectStore('data');const req=store.get('main');let issue;req.onsuccess=()=>{try{const latest=req.result||initial();if(latest.revision!==db.revision){db=latest;render();throw Error('Los datos cambiaron en otra ventana. Revisa el registro y vuelve a guardar.');}next=structuredClone(db);change(next);next.revision++;store.put(next,'main');}catch(e){issue=e;t.abort();}};t.oncomplete=resolve;t.onerror=()=>reject(issue||t.error);t.onabort=()=>reject(issue||t.error||Error('No se pudo guardar.'));});db=next;}catch(e){if(e.name==='QuotaExceededError')throw Error('No hay espacio suficiente. Descarga una copia de seguridad y libera espacio en el teléfono.');throw e;}finally{busy=false;}}
const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const stat=(label,value,note='',cls='')=>`<article class="stat ${cls}"><span>${label}</span><strong>${value}</strong>${note?`<small>${note}</small>`:''}</article>`;
const empty=(title,text,action,label)=>`<div class="empty"><div class="empty-icon">${icon('package-open')}</div><h3>${title}</h3><p>${text}</p>${action?btn(label,action,'primary'):''}</div>`;
function visitRows(visits){return visits.length?visits.map(v=>`<button class="visit-row" data-action="visit-detail" data-id="${v.id}"><span class="shop-icon">${icon('store')}</span><span class="visit-info"><strong>${esc(shopName(v))}</strong><span>${time(v.createdAt)} · ${units(v)} vendidas${v.gifts?` · ${v.gifts} cortesía`:''}${v.replacements?` · ${v.replacements} cambio`:''}</span></span><span class="visit-price"><strong>${money(sale(v))}</strong><small class="${debt(db,v)?'amber':'green'}">${debt(db,v)?`${money(debt(db,v))} pendiente`:'Pagado'} ${v.photos.length?icon('camera'):''}</small></span></button>`).join(''):empty('Tu próxima tienda va aquí','Registra las cantidades y toma una foto al llegar.');}
function home(){const r=lastRoute();const s=r?routeStats(db,r):null;const visits=db.visits.filter(v=>v.date===today());const sold=visits.reduce((z,v)=>z+sale(v),0);const received=db.receipts.filter(x=>x.date===today()).reduce((z,x)=>z+x.amount,0);return `<div class="page-heading"><div><p class="eyebrow">${esc(dateLabel(today()))}</p><h1>Tu jornada, en orden.</h1><p>Hola, ${esc(db.settings.name)}. Todo listo para tu ruta.</p></div><span class="date-chip">${icon('wheat')} PAN DE QUINUA</span></div><section class="route-banner"><div class="route-banner-head"><span class="tag">${r&&!r.closed?'Ruta en curso':r?'Última ruta cerrada':'Comienza tu jornada'}</span><span>${icon('truck')}</span></div><div class="route-banner-main"><div><p>${r?'Fundas nuevas en el carro':'Carga inicial del carro'}</p><div class="stock-number">${s?(r.closed?r.actual:s.expected):'—'} <span>fundas</span></div><p class="banner-caption">${r?`${r.initial} de salida${s.reload?` + ${s.reload} de recarga`:''} · ${esc(dateLabel(r.date))}`:'Cuenta las fundas antes de salir.'}</p></div><div class="banner-action">${active()?btn(`${icon('map-pin')} Registrar entrega aquí`,'visit-here','light'):btn(`${icon('play')} Iniciar ruta`,'start-route','light')}${active()?`<button class="text-button" data-action="nav" data-view="route">Ver inventario de ruta</button>${btn('Registrar sin GPS','visit','quiet')}`:''}</div></div>${s?`<div class="banner-bottom"><span>${s.sold} vendidas</span><span>${s.gifts} cortesías</span><span>${s.replacements} cambios</span><span>${s.expired} caducadas retiradas</span></div>`:''}</section><div class="stats-grid">${stat('Ventas de hoy',money(sold),`${visits.reduce((z,v)=>z+units(v),0)} fundas vendidas`)}${stat('Cobrado hoy',money(received),'Efectivo + transferencias')}${stat('Saldo por cobrar',money(db.visits.reduce((z,v)=>z+debt(db,v),0)),'Todas las tiendas','debt-stat')}</div><div class="home-columns"><section class="panel"><div class="section-head"><h2>Visitas de hoy <span class="counter">${visits.length}</span></h2>${btn('Ver ruta','nav','quiet','data-view="route"')}</div><div>${visitRows([...visits].reverse())}</div></section><aside><section class="panel quick-panel"><h2>Al final del día</h2><p>Cuenta el pan, cuadra el efectivo y prepara el reporte para tu jefe.</p>${btn(`${icon('clipboard-check')} ${active()?'Cerrar ruta':'Ver cierre de ruta'}`,'close-route','outline',!r?'disabled':'')}${btn(`${icon('file-spreadsheet')} Reporte Excel`,'nav','outline','data-view="reports"')}</section><div class="local-note">${icon('hard-drive')}<div><strong>Guardado en este celular</strong><p>Las fotos y los registros permanecen aquí. Descarga una copia de seguridad para conservarlos.</p><button class="text-link" data-action="backup">Descargar copia</button></div></div></aside></div>`;}
function routePage(){const r=lastRoute();if(!r)return `<div class="page-heading"><div><p class="eyebrow">CONTROL DEL CARRO</p><h1>Tu ruta</h1></div></div>${empty('Antes de salir','Ingresa las fundas cargadas y el efectivo inicial.','start-route','Iniciar ruta')}`;const s=routeStats(db,r);return `<div class="page-heading"><div><p class="eyebrow">${esc(dateLabel(r.date))}</p><h1>${r.closed?'Cierre de ruta':'Ruta en curso'}</h1></div><div class="button-row">${r.closed?btn('Iniciar otra ruta','start-route','primary'):btn(`${icon('plus')} Nueva visita`,'visit','primary')}${btn(`${icon('trash-2')} Eliminar ruta`,'delete-route','outline',`data-id="${r.id}"`)}</div></div><div class="route-columns"><section class="panel inventory"><h2>Inventario de fundas nuevas</h2>${stockTable(r)}<div class="inventory-row"><span>Cargadas al salir</span><strong>${r.initial}</strong></div><div class="inventory-row"><span>Recargas en ruta</span><strong>+ ${s.reload}</strong></div><div class="inventory-row"><span>Vendidas</span><strong>− ${s.sold}</strong></div><div class="inventory-row"><span>Cortesías</span><strong>− ${s.gifts}</strong></div><div class="inventory-row"><span>Entregadas por cambio</span><strong>− ${s.replacements}</strong></div><div class="inventory-total"><span>Regreso esperado</span><strong>${s.expected}</strong></div>${r.closed?`<div class="inventory-row"><span>Conteo físico</span><strong>${r.actual}</strong></div><div class="reconcile ${stockMatches(r)?'ok':'warning'}">${icon(stockMatches(r)?'check-circle':'triangle-alert')} ${stockMatches(r)?'Inventario cuadrado':`Diferencia: ${r.actual-s.expected} fundas. Revisa el desglose por tipo.`}</div>`:btn(`${icon('package-plus')} Agregar recarga`,'reload','outline full')}<div class="expired-note">${icon('rotate-ccw')}<span><strong>${s.expired} caducadas retiradas</strong><br>Van aparte del pan vendible.${r.closed?` Conteo físico: ${r.actualExpired}. Diferencia: ${r.actualExpired-s.expired}.`:''}</span></div></section><section class="panel inventory"><h2>Dinero de la ruta</h2><div class="inventory-row"><span>Ventas nuevas</span><strong>${money(s.sales)}</strong></div><div class="inventory-row"><span>Efectivo inicial</span><strong>${money(r.openingCash)}</strong></div><div class="inventory-row"><span>Cobros en efectivo</span><strong>+ ${money(s.cash)}</strong></div><div class="inventory-row"><span>Gastos en efectivo</span><strong>− ${money(db.expenses.filter(e=>e.routeId===r.id&&e.method==='cash').reduce((z,e)=>z+e.amount,0))}</strong></div><div class="inventory-total"><span>Efectivo esperado</span><strong>${money(s.cashExpected)}</strong></div><div class="inventory-row"><span>Transferencias recibidas</span><strong>${money(s.transfer)}</strong></div>${r.closed?`<div class="inventory-row"><span>Efectivo contado</span><strong>${money(r.actualCash)}</strong></div><div class="reconcile ${r.actualCash===s.cashExpected?'ok':'warning'}">${icon(r.actualCash===s.cashExpected?'check-circle':'triangle-alert')} ${r.actualCash===s.cashExpected?'Efectivo cuadrado':`Diferencia: ${money(r.actualCash-s.cashExpected)}`}</div>${r.note?`<p class="subtext">${esc(r.note)}</p>`:''}`:btn(`${icon('clipboard-check')} Cerrar ruta`,'close-route','primary full')}</section></div><section class="panel"><div class="section-head"><h2>Tiendas visitadas <span class="counter">${s.visits.length}</span></h2></div>${visitRows([...s.visits].reverse())}</section>${db.routes.length>1?`<section class="panel history"><h2>Rutas anteriores</h2>${[...db.routes].reverse().filter(x=>x.id!==r.id).map(x=>`<button class="history-row" data-action="route-detail" data-id="${x.id}"><span>${esc(dateLabel(x.date))} · ${routeStats(db,x).visits.length} visitas</span><strong>${x.closed?'Cerrada':'En curso'}</strong></button>`).join('')}</section>`:''}`;}
function shopsPage(){const shops=db.shops.filter(s=>(s.name+' '+s.address).toLowerCase().includes(shopQuery.toLowerCase()));return `<div class="page-heading"><div><p class="eyebrow">TUS CLIENTES</p><h1>Tiendas</h1><p>Precios habituales e historial de cada tienda.</p></div>${btn(`${icon('plus')} Agregar tienda`,'shop','primary')}</div><div class="search-bar">${icon('search')}<input id="shop-search" aria-label="Buscar tienda" placeholder="Buscar tienda o sector…" value="${esc(shopQuery)}"></div><div class="shop-grid">${shops.length?shops.map(s=>{const vs=db.visits.filter(v=>v.shopId===s.id);const d=vs.reduce((z,v)=>z+debt(db,v),0);return `<button class="panel shop-card" data-action="shop-detail" data-id="${s.id}"><span class="shop-icon">${icon('store')}</span><h2>${esc(s.name)}</h2><p>${esc(s.address||'Sin dirección registrada')}</p><div class="shop-card-bottom"><span>Precio habitual <strong>${money(s.price)}</strong></span><span class="${d?'amber':'green'}">${d?`${money(d)} pendiente`:'Sin pendientes'}</span></div><small>${vs.length} visitas registradas</small></button>`;}).join(''):empty(shopQuery?'Sin coincidencias':'Tu primera tienda','Guarda su nombre, sector y precio habitual.','shop','Agregar tienda')}</div>`;}
function finance(){const ar=active();const pending=db.visits.reduce((z,v)=>z+debt(db,v),0);const rs=db.receipts.filter(x=>x.date===today());const ex=db.expenses.filter(x=>x.date===today());const exp=ex.reduce((z,e)=>z+e.amount,0);return `<div class="page-heading"><div><p class="eyebrow">VENTAS, COBROS Y GASTOS</p><h1>Finanzas</h1></div><div class="button-row">${btn(`${icon('wallet')} Registrar cobro`,'receipt','primary',!ar?'disabled':'')}${btn(`${icon('minus')} Agregar gasto`,'expense','outline',!ar?'disabled':'')}</div></div>${!ar?`<div class="notice">Inicia una ruta para registrar cobros y gastos del día.</div>`:''}<div class="stats-grid">${stat('Cobrado hoy',money(rs.reduce((z,r)=>z+r.amount,0)),'Incluye deudas anteriores')}${stat('Gastos de hoy',money(exp),'Efectivo + transferencia')}${stat('Saldo por cobrar',money(pending),'Saldo actual de todas las ventas')}</div><section class="panel"><div class="section-head"><h2>Tiendas con saldo pendiente</h2></div>${db.shops.filter(s=>db.visits.filter(v=>v.shopId===s.id).some(v=>debt(db,v)>0)).map(s=>`<div class="debt-row"><div><strong>${esc(s.name)}</strong><small>${db.visits.filter(v=>v.shopId===s.id&&debt(db,v)>0).length} entregas pendientes</small></div><strong>${money(db.visits.filter(v=>v.shopId===s.id).reduce((z,v)=>z+debt(db,v),0))}</strong>${btn('Cobrar','receipt','outline',`data-id="${s.id}" ${!ar?'disabled':''}`)}</div>`).join('')||empty('Todo al día','No tienes ventas pendientes de cobro.')}</section><section class="panel"><div class="section-head"><h2>Movimientos recientes</h2></div>${[...db.receipts.map(x=>({...x,type:'receipt'})),...db.expenses.map(x=>({...x,type:'expense'}))].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,40).map(x=>`<div class="transaction-row"><span class="transaction-icon">${icon(x.type==='receipt'?'banknote':'receipt')}</span><div><strong>${esc(x.type==='receipt'?(db.shops.find(s=>s.id===x.shopId)?.name):x.description)}</strong><small>${x.date} · ${x.method==='cash'?'Efectivo':'Transferencia'} · ${x.type==='receipt'?'Cobro':'Gasto'}</small></div><strong class="${x.type==='receipt'?'green':'amber'}">${x.type==='receipt'?'+':'−'}${money(x.amount)}</strong>${db.routes.find(r=>r.id===x.routeId)?.closed?'':`<button class="icon-button" aria-label="Anular ${x.type==='receipt'?'cobro':'gasto'}" data-action="delete-movement" data-id="${x.id}" data-type="${x.type}">${icon('trash-2')}</button>`}</div>`).join('')||empty('Sin movimientos','Aquí aparecerán tus cobros y gastos.')}</section>`;}
function reportsPage(){const vs=db.visits.filter(v=>v.date>=reports.start&&v.date<=reports.end);const routes=db.routes.filter(r=>r.date>=reports.start&&r.date<=reports.end);return `<div class="page-heading"><div><p class="eyebrow">PARA TU JEFE</p><h1>Reportes</h1><p>Todas las cantidades, el dinero y las fotos en un Excel.</p></div></div><section class="panel report-panel"><div class="report-top"><div class="report-file">${icon('file-spreadsheet')}</div><div><h2>Reporte de ruta</h2><p>Elige un día o un rango de fechas.</p></div></div><div class="preset-row">${btn('Hoy','range-today','chip')}${btn('Esta semana','range-week','chip')}${btn('Este mes','range-month','chip')}</div><div class="form-grid"><label>Desde<input type="date" id="report-start" value="${reports.start}" required></label><label>Hasta<input type="date" id="report-end" value="${reports.end}" required></label></div><div class="report-summary"><span><strong>${routes.length}</strong> rutas</span><span><strong>${vs.length}</strong> visitas</span><span><strong>${vs.reduce((z,v)=>z+v.photos.length,0)}</strong> fotos</span><span><strong>${money(vs.reduce((z,v)=>z+sale(v),0))}</strong> vendido</span></div><p class="subtext">Incluye resumen, visitas, precios utilizados, inventario, contabilidad y fotos insertadas. Las rutas abiertas se marcan como provisionales.</p>${btn(`${icon('download')} Descargar Excel (.xlsx)`,'excel','primary full',!routes.length?'disabled':'')}</section><section class="panel"><div class="section-head"><h2>Copia de seguridad</h2>${icon('shield-check')}</div><p class="subtext">Guarda todos tus registros y fotografías en un archivo. Puedes restaurarlo en otro celular. El Excel es tu reporte; esta copia conserva los datos de la app.</p><div class="button-row">${btn(`${icon('download')} Descargar copia`,'backup','outline')}${btn(`${icon('upload')} Restaurar copia`,'restore','quiet')}</div><input type="file" id="restore-input" accept="application/json,.json" hidden></section>`;}
function render(){if(!db)return;const tabs=[['home','Inicio','layout-dashboard'],['route','Ruta','truck'],['map','Mapa','map-pin'],['shops','Tiendas','store'],['finance','Finanzas','wallet'],['reports','Reportes','file-spreadsheet']];$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="home"><span class="brand-icon">${icon('wheat')}</span><span>Quinua<span class="brand-light">Ruta</span></span></a><div class="sidebar-caption">MI CONTROL DE RUTA</div><nav aria-label="Navegación principal">${tabs.map(([v,t,i])=>`<button class="nav-item ${view===v?'selected':''}" data-action="nav" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${v==='route'&&active()?'<span class="nav-live">En curso</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="unit-price">Precio base <strong>${money(db.settings.price)}</strong></span>${btn(`${icon('settings')} Ajustes`,'settings','quiet full')}<div class="profile"><span>${esc(db.settings.name.trim().charAt(0).toUpperCase())}</span><div><strong>${esc(db.settings.name)}</strong><small>Mi ruta de quinua</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><span class="breadcrumb">Mi negocio <span>/</span> ${tabs.find(t=>t[0]===view)?.[1]}</span><div class="topbar-actions"><span class="connection">${icon(navigator.onLine?'wifi':'wifi-off')} ${navigator.onLine?'Listo para la ruta':'Sin conexión'}</span>${installPrompt?btn(`${icon('smartphone')} Instalar`,'install','quiet'):''}<button class="icon-button mobile-settings" data-action="settings" aria-label="Ajustes">${icon('settings')}</button></div></header><main>${({home,route:routePage,shops:shopsPage,finance,reports:reportsPage,map:mapPage}[view])()}</main><footer class="app-footer">Quinua Ruta <span>Precio base ${money(db.settings.price)} · USD</span></footer></div><nav class="mobile-nav" aria-label="Navegación del celular">${tabs.map(([v,t,i])=>`<button class="${view===v?'selected':''}" data-action="nav" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav></div>`;drawIcons();if(view==='map')renderMap();}
function drawIcons(){createIcons({icons,attrs:{'stroke-width':1.7}});}
function closeModal(){const el=$('#modal-root');el.innerHTML='';document.body.classList.remove('modal-open');modalPhotos=[];modalLocation=null;modalReturn?.focus();}
function modal(title,body,wide=false){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="modal-close" aria-label="Cerrar ventana">${icon('x')}</button></header><div class="modal-body">${body}</div></section></div>`;document.body.classList.add('modal-open');drawIcons();setTimeout(()=>$('.modal input:not([type="hidden"]),.modal select,.modal button')?.focus(),30);}
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const qtyField=(label,name,value=0)=>field(label,name,value,'number','min="0" step="1" inputmode="numeric" required');
const cashField=(label,name,value=0)=>field(label,name,(value/100).toFixed(2),'number','min="0" step="0.01" inputmode="decimal" required');
const formEnd=(label)=>`<p class="form-error" role="alert"></p><div class="form-actions">${btn('Cancelar','modal-close','quiet')}<button class="btn primary" type="submit">${label}</button></div>`;
function productOptions(){const r=active();return r&&(!r.initialByType||r.initialByType['sin-clasificar']||r.reloads.some(x=>!x.byType||x.byType['sin-clasificar'])||db.visits.some(v=>v.routeId===r.id&&v.lines.some(l=>!l.productId||l.productId==='sin-clasificar')))?ALL_PRODUCTS:PRODUCTS;}
function typeFields(title,prefix,values={},products=productOptions(),fallback=0){return `<fieldset class="type-fields"><legend>${title}</legend><div class="form-grid">${products.map(p=>qtyField(p.name,`${prefix}_${p.id}`,values[p.id]??fallback)).join('')}</div></fieldset>`;}
function readTypes(f,prefix,products){return Object.fromEntries(products.map(p=>[p.id,integer(f[`${prefix}_${p.id}`],p.name)]));}
function movementFields(title,key,v){return `<details class="type-movement" ${v?.[key]?'open':''}><summary data-title="${title}">${title} · <span class="movement-total">${v?.[key]||0}</span> fundas</summary>${typeFields(title,key,typeMap(v?.[key+'ByType'],v?.[key]||0))}</details>`;}
function stockMatches(r){return r.actual===routeStats(db,r).expected&&Object.entries(routeTypes(db,r)).every(([k,t])=>(typeMap(r.actualByType,r.actual)[k]||0)===t.expected);}
function stockTable(r){const stats=routeTypes(db,r);return `<div class="table-scroll"><table class="type-table"><thead><tr><th>Tipo</th><th>Salida</th><th>Disponible / esperado</th><th>Caducadas retiradas</th>${r.closed?'<th>Físico</th><th>Diferencia</th>':''}</tr></thead><tbody>${ALL_PRODUCTS.filter(p=>p.id!=='sin-clasificar'||Object.values(stats[p.id]).some(Boolean)).map(p=>`<tr><td>${p.name}</td><td>${stats[p.id].initial}</td><td>${stats[p.id].expected}</td><td>${stats[p.id].expired}</td>${r.closed?`<td>${typeMap(r.actualByType,r.actual)[p.id]||0}</td><td>${(typeMap(r.actualByType,r.actual)[p.id]||0)-stats[p.id].expected}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function visitTypeTable(v){const types=visitTypes(v);return `<div class="table-scroll"><table class="type-table"><thead><tr><th>Tipo</th><th>Venta</th><th>Cortesía</th><th>Cambio</th><th>Caducadas</th></tr></thead><tbody>${ALL_PRODUCTS.filter(p=>Object.values(types[p.id]).some(Boolean)).map(p=>{const t=types[p.id];return `<tr><td>${p.name}</td><td>${t.sold}</td><td>${t.gifts}</td><td>${t.replacements}</td><td>${t.expired}</td></tr>`;}).join('')}</tbody></table></div>`;}
async function captureLocation(){if(!navigator.geolocation)throw Error('Este navegador no ofrece ubicación. Selecciona una tienda guardada.');const form=$('#visit-form');const buttons=$$('[data-action="capture-location"]');buttons.forEach(b=>b.disabled=true);toast('Buscando tu ubicación…');try{const loc=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,capturedAt:now(),source:'gps'}),e=>reject(Error(e.code===1?'Permiso de ubicación denegado. Puedes activarlo en el navegador o elegir una tienda.':'No se pudo obtener la ubicación. Vuelve a intentarlo o selecciona una tienda.')),{enableHighAccuracy:true,timeout:15000,maximumAge:0}));validateLocation(loc);if(form!==$('#visit-form'))return;modalLocation=loc;renderLocation();toast('Ubicación lista. Revisa el pin antes de guardar.');}finally{buttons.forEach(b=>b.disabled=false);}}
function renderLocation(){const el=$('#visit-location');if(!el)return;if(!modalLocation){el.innerHTML='<p class="subtext">Usa el GPS para guardar un punto, o selecciona una tienda existente.</p>';return;}const loc=modalLocation;el.innerHTML=`<div class="notice small"><strong>Ubicación lista</strong><p id="location-coordinates">${loc.lat.toFixed(6)}, ${loc.lng.toFixed(6)} · ${loc.source==='manual'?'Pin ajustado':`Precisión aproximada: ${Math.round(loc.accuracy)} m`}</p><p>Arrastra el pin o toca el mapa para corregirlo.</p>${btn('Quitar ubicación','clear-location','quiet')}</div><div id="location-map" class="delivery-map small-map">Cargando mapa…</div>`;showMap($('#location-map'),[loc],{edit:true,onMove:pos=>{modalLocation={lat:pos.lat,lng:pos.lng,accuracy:null,capturedAt:now(),source:'manual'};$('#location-coordinates').textContent=`${pos.lat.toFixed(6)}, ${pos.lng.toFixed(6)} · Pin ajustado`;}});}
function mapVisits(){return db.visits.filter(v=>v.location&&(!mapDate||v.date===mapDate));}
function mapPage(){const vs=mapVisits(),missing=db.visits.filter(v=>!v.location&&(!mapDate||v.date===mapDate)).length;return `<div class="page-heading"><div><p class="eyebrow">PUNTOS DE ENTREGA</p><h1>Tu mapa</h1><p>${vs.length} entregas con ubicación${missing?` · ${missing} visitas sin ubicación`:''}</p></div>${active()?btn('Registrar entrega aquí','visit-here','primary'):''}</div><section class="panel map-panel"><label>Fecha (vacía para todas)<input id="map-date" type="date" value="${mapDate}"></label><p class="subtext">Toca un pin para ver la entrega. El mapa de calles necesita conexión; los registros y sus coordenadas se conservan sin señal.</p><div id="deliveries-map" class="delivery-map">Cargando mapa…</div></section><section class="panel">${visitRows([...vs].reverse())}</section>`;}
function renderMap(){showMap($('#deliveries-map'),mapVisits().map(v=>({...v.location,popup:`<strong>${esc(shopName(v))}</strong><p>${esc(dateLabel(v.date))} · ${units(v)} vendidas · ${v.gifts} cortesías · ${v.replacements} cambios<br>${money(sale(v))} · ${money(debt(db,v))} pendiente · ${v.photos.length} fotos</p>${btn('Ver entrega','visit-detail','quiet',`data-id="${v.id}"`)}<a href="${mapsURL(v.location)}" target="_blank" rel="noopener">Google Maps</a>`})));}
function deleteRoutePrompt(routeId){const info=routeDeletionInfo(db,routeId);if(info.linkedRoutes.length){modal('Ruta con cobros posteriores',`<p>La ruta del <strong>${esc(dateLabel(info.route.date))}</strong> tiene entregas cobradas en otras rutas. Para eliminarla, elimina primero las rutas donde registraste esos cobros:</p><div class="button-row">${info.linkedRoutes.map(r=>btn(`${esc(dateLabel(r.date))} · Ver ruta`,'route-detail','outline',`data-id="${r.id}"`)).join('')}</div><p class="subtext">Así los cobros quedan vinculados a sus ventas y las cuentas se conservan.</p><div class="form-actions">${btn('Volver','modal-close','quiet')}</div>`);return;}modal('Eliminar ruta',`<p>Vas a eliminar la ruta del <strong>${esc(dateLabel(info.route.date))}</strong> (${info.route.closed?'cerrada':'en curso'}).</p><div class="notice"><strong>También se eliminarán:</strong><br>${info.visits} visitas · ${info.photos} fotos · ${info.locations} puntos del mapa<br>${info.receipts} cobros · ${info.expenses} gastos<br>La carga, las recargas y el cierre de esta ruta.</div>${info.reopenedDebt?`<p>Al borrar sus cobros, ${money(info.reopenedDebt)} de entregas de otras rutas volverán a estar pendientes.</p>`:''}<p class="subtext">Las tiendas guardadas y las demás rutas se conservan. No se puede deshacer; puedes descargar una copia antes de eliminarla.</p><div class="form-actions">${btn('Descargar copia','backup','outline')}${btn('Cancelar','modal-close','quiet')}${btn('Eliminar esta ruta','confirm-delete-route','danger',`data-id="${routeId}"`)}</div>`);}
function startRoute(){if(active())throw Error('Ya tienes una ruta abierta.');modal('Iniciar ruta',`<form id="start-form"><p class="subtext">Cuenta el pan nuevo y el efectivo antes de salir.</p>${field('Fecha de ruta','date',today(),'date','required')}${typeFields('Fundas cargadas al salir','initial',{},PRODUCTS)}${cashField('Efectivo inicial ($)','openingCash',0)}<div class="notice small">Las fundas caducadas se registran aparte cuando las retiras de las tiendas.</div>${formEnd('Iniciar ruta')}</form>`);}
function shopForm(shop=null){modal(shop?'Editar tienda':'Agregar tienda',`<form id="shop-form" data-id="${shop?.id||''}">${field('Nombre de la tienda','name',shop?.name||'','text','maxlength="100" required')}${field('Dirección o sector','address',shop?.address||'','text','maxlength="250"')}${field('Teléfono','phone',shop?.phone||'','tel','maxlength="30"')}${cashField('Precio habitual por funda ($)','price',shop?.price??db.settings.price)}<label>Notas<textarea name="notes" maxlength="1000">${esc(shop?.notes||'')}</textarea></label>${formEnd('Guardar tienda')}</form>`);}
function priceLine(qty=0,price=db.settings.price,reason='',productId=productOptions()[0].id){return `<div class="price-line"><label class="product-select">Tipo<select name="productId">${productOptions().map(p=>`<option value="${p.id}" ${p.id===productId?'selected':''}>${p.name}</option>`).join('')}</select></label>${qtyField('Fundas vendidas','qty',qty)}${cashField('Precio por funda ($)','price',price)}<button type="button" class="icon-button remove-price" aria-label="Quitar línea de precio">${icon('x')}</button><label class="price-reason">Motivo de precio especial<input name="reason" placeholder="Acuerdo con tienda, promoción…" value="${esc(reason)}" maxlength="200"></label></div>`;}
function visitForm(v=null){const r=active();if(!r)throw Error('Inicia una ruta antes de registrar visitas.');modalPhotos=structuredClone(v?.photos||[]);modalLocation=structuredClone(v?.location||null);modal(v?'Corregir visita':'Registrar visita',`<form id="visit-form" data-id="${v?.id||''}"><div class="notice small">${routeStats(db,r).expected} fundas nuevas disponibles en el carro.</div><div id="visit-location"></div>${btn(`${icon('locate-fixed')} Usar mi ubicación`,'capture-location','outline')}<label>Tienda o punto guardado<select name="shopId" id="visit-shop" ${v?'disabled':''}><option value="">Nuevo punto por ubicación</option>${db.shops.map(s=>`<option value="${s.id}" ${v?.shopId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${v?'':field('Nombre del punto (opcional)','pointName','','text','maxlength="100" placeholder="Se asigna un nombre automáticamente"')}<div id="price-lines">${(v?.lines||[{qty:0,price:db.settings.price,reason:''}]).map(l=>priceLine(l.qty,l.price,l.reason,l.productId||(v?'sin-clasificar':productOptions()[0].id))).join('')}</div>${btn(`${icon('plus')} Otro tipo o precio`,'add-price','quiet')}${movementFields('Cortesías','gifts',v)}${movementFields('Nuevas entregadas por cambio','replacements',v)}${movementFields('Caducadas retiradas','expired',v)}${field('Caducidad de la entrega','expiry',v?.expiry||'','date')}<div class="live-total"><span>Venta de esta visita</span><strong id="visit-total">${money(v?sale(v):0)}</strong></div>${v?`<div class="notice small">Ya cobrado: ${money(paid(db,v.id))}. Registra nuevos abonos en Finanzas.</div>`:`<div class="payment-presets">${btn('Pago completo','full-payment','chip')}${btn('Queda pendiente','credit-payment','chip')}</div><div class="form-grid">${cashField('Cobrado ahora ($)','paid',0)}<label>Forma de pago<select name="method"><option value="cash">Efectivo</option><option value="transfer">Transferencia</option></select></label></div>`}<label>Observaciones<textarea name="notes" placeholder="Producto en exhibición, pedido para mañana…" maxlength="2000">${esc(v?.notes||'')}</textarea></label><div class="photo-label"><strong>Fotos de la visita</strong><span>Hasta 6 fotos</span></div><div id="photo-previews"></div><div class="photo-actions"><label class="btn outline photo-button">${icon('camera')} Tomar foto<input type="file" id="camera-input" accept="image/*" capture="environment"></label><label class="btn quiet photo-button">${icon('image-plus')} Galería<input type="file" id="gallery-input" accept="image/*" multiple></label></div>${formEnd(v?'Guardar corrección':'Guardar visita')}</form>`,true);renderPhotos();renderLocation();}
function renderPhotos(){const target=$('#photo-previews');if(!target)return;target.innerHTML=modalPhotos.map((p,i)=>`<div class="photo-preview"><img src="${p.data}" alt="Evidencia ${i+1}"><button type="button" class="photo-remove" data-action="remove-photo" data-index="${i}" aria-label="Quitar foto ${i+1}">${icon('x')}</button></div>`).join('');drawIcons();}
function lineInputs(){return $$('#price-lines .price-line').map(el=>({productId:el.querySelector('[name="productId"]').value,qty:integer(el.querySelector('[name="qty"]').value),price:cents(el.querySelector('[name="price"]').value,'Precio'),reason:el.querySelector('[name="reason"]').value.trim()}));}
function updateTotal(){for(const section of $$('.type-movement')){const n=[...section.querySelectorAll('input')].reduce((sum,x)=>sum+(Number(x.value)||0),0);section.querySelector('.movement-total').textContent=n;}try{$('#visit-total').textContent=money(lineInputs().reduce((z,l)=>z+l.qty*l.price,0));}catch{}}
function visitDetail(v){const r=db.routes.find(r=>r.id===v.routeId);modal(esc(shopName(v)),`<p class="subtext">${esc(dateLabel(v.date))} · ${time(v.createdAt)}</p><div class="detail-numbers"><span><strong>${units(v)}</strong> vendidas</span><span><strong>${v.gifts}</strong> cortesía</span><span><strong>${v.replacements}</strong> cambio</span><span><strong>${v.expired}</strong> caducadas</span></div>${v.lines.filter(l=>l.qty).map(l=>`<div class="inventory-row"><span>${l.qty} fundas × ${money(l.price)}${l.reason?`<small>${esc(l.reason)}</small>`:''}</span><strong>${money(l.qty*l.price)}</strong></div>`).join('')}<div class="inventory-total"><span>Venta</span><strong>${money(sale(v))}</strong></div><div class="inventory-row"><span>Cobrado acumulado</span><strong>${money(paid(db,v.id))}</strong></div><div class="inventory-row"><span>Pendiente actual</span><strong>${money(debt(db,v))}</strong></div>${v.expiry?`<p>Caducidad de la entrega: ${esc(v.expiry)}</p>`:''}${v.notes?`<p class="detail-notes">${esc(v.notes)}</p>`:''}${visitTypeTable(v)}${v.location?`<p><a href="${mapsURL(v.location)}" target="_blank" rel="noopener">Abrir punto en Google Maps</a></p>`:''}<div class="evidence-grid">${v.photos.map((p,i)=>`<a href="${p.data}" download="Foto_${i+1}.jpg"><img src="${p.data}" alt="Evidencia de ${esc(shopName(v))}"></a>`).join('')||'<p class="subtext">Sin fotos en esta visita.</p>'}</div>${!r.closed?btn(`${icon('pencil')} Corregir visita`,'edit-visit','outline',`data-id="${v.id}"`):'<p class="subtext">Ruta cerrada. Los cobros posteriores se registran en una nueva ruta.</p>'}`,true);}
function shopDetail(s){const vs=db.visits.filter(v=>v.shopId===s.id);modal(esc(s.name),`<p>${esc(s.address||'Sin dirección registrada')}</p>${s.phone?`<p>Teléfono: ${esc(s.phone)}</p>`:''}<div class="inventory-row"><span>Precio habitual</span><strong>${money(s.price)}</strong></div><div class="inventory-row"><span>Saldo por cobrar</span><strong>${money(vs.reduce((z,v)=>z+debt(db,v),0))}</strong></div>${s.notes?`<p>${esc(s.notes)}</p>`:''}${btn(`${icon('pencil')} Editar tienda`,'edit-shop','outline',`data-id="${s.id}"`)}<h3 class="detail-heading">Historial de visitas</h3>${visitRows([...vs].reverse())}`,true);}
function closeRoute(){const r=lastRoute();if(!r)throw Error('Aún no hay ninguna ruta.');if(r.closed){navTo('route');return;}const s=routeStats(db,r);modal('Cerrar ruta',`<form id="close-form"><p class="subtext">Cuenta lo que regresa y el dinero que tienes físicamente.</p>${stockTable(r)}<div class="notice">Esperado: <strong>${s.expected} fundas nuevas</strong> · <strong>${money(s.cashExpected)} efectivo</strong><br>Caducadas retiradas: <strong>${s.expired}</strong></div><div class="form-grid">${typeFields('Fundas nuevas que regresan','actual',{},productOptions(),'')}${typeFields('Caducadas que regresan','actualExpired',{},productOptions(),'')}</div>${cashField('Efectivo contado ($)','actualCash',0)}<div id="close-preview" class="subtext"></div><label>Nota de cierre<textarea name="note" placeholder="Explica cualquier diferencia…" maxlength="2000"></textarea></label><div class="notice small">Revisa las visitas antes de cerrar. La ruta quedará cerrada y podrás generar el Excel.</div>${formEnd('Confirmar cierre')}</form>`);}
function receiptForm(shopId=''){if(!active())throw Error('Inicia una ruta para registrar un cobro.');const shops=db.shops.filter(s=>db.visits.some(v=>v.shopId===s.id&&debt(db,v)>0));if(!shops.length)throw Error('No hay saldos pendientes de cobro.');modal('Registrar cobro',`<form id="receipt-form"><p class="subtext">El abono se aplica primero a las entregas pendientes más antiguas.</p><label>Tienda<select name="shopId" id="receipt-shop" required>${shops.map(s=>`<option value="${s.id}" ${s.id===shopId?'selected':''}>${esc(s.name)} · ${money(db.visits.filter(v=>v.shopId===s.id).reduce((z,v)=>z+debt(db,v),0))}</option>`).join('')}</select></label>${cashField('Valor recibido ($)','amount',0)}<label>Forma de pago<select name="method"><option value="cash">Efectivo</option><option value="transfer">Transferencia</option></select></label>${field('Observación o referencia','note','','text','maxlength="500"')}${formEnd('Guardar cobro')}</form>`);}
function expenseForm(){if(!active())throw Error('Inicia una ruta primero.');modal('Agregar gasto',`<form id="expense-form">${field('Detalle del gasto','description','','text','placeholder="Combustible, parqueo…" maxlength="200" required')}${cashField('Valor ($)','amount',0)}<label>Pagado con<select name="method"><option value="cash">Efectivo del carro</option><option value="transfer">Transferencia</option></select></label>${formEnd('Guardar gasto')}</form>`);}
function settings(){modal('Ajustes',`<form id="settings-form">${field('Tu nombre','name',db.settings.name,'text','required maxlength="60"')}${cashField('Precio base por funda ($)','price',db.settings.price)}<label>Costo por funda ($), opcional<input name="cost" type="number" step="0.01" min="0" value="${db.settings.cost===null?'':(db.settings.cost/100).toFixed(2)}" inputmode="decimal" placeholder="Déjalo vacío si no lo conoces"></label><p class="subtext">El costo se guarda al iniciar cada ruta. La ganancia estimada descuenta el costo de vendidas, cortesías y reposiciones, más los gastos.</p>${formEnd('Guardar ajustes')}</form><div class="install-info"><h3>Instalar en tu Android</h3><p>Abre la app en Chrome. En el menú ⋮ elige <strong>Instalar aplicación</strong> o <strong>Agregar a pantalla de inicio</strong>.</p>${installPrompt?btn('Instalar ahora','install','outline'):''}<p class="subtext" id="offline-ready">Abre la app con conexión una vez para preparar el uso sin señal.</p></div>`);if(navigator.serviceWorker)navigator.serviceWorker.ready.then(()=>{$('#offline-ready')&&($('#offline-ready').textContent='La app está preparada para abrirse sin señal en este dispositivo.');});}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function excel(){if(reports.start>reports.end)throw Error('La fecha inicial debe ser anterior a la final.');const button=$('[data-action="excel"]');if(button){button.disabled=true;button.textContent='Preparando Excel y fotos…';}try{const blob=await makeExcel(db,reports.start,reports.end);download(blob,`Reporte_Quinua_${reports.start}${reports.start===reports.end?'':'_'+reports.end}.xlsx`);toast('Excel listo. Encuéntralo en Descargas para enviarlo a tu jefe.');}finally{if(view==='reports')render();}}
function backup(){download(new Blob([JSON.stringify(db)],{type:'application/json'}),`Copia_Quinua_Ruta_${today()}.json`);toast('Copia descargada con todos tus registros y fotos.');}
async function compress(file){if(!file.type.startsWith('image/'))throw Error('Selecciona una imagen.');if(file.size>25*1024*1024)throw Error('La foto es demasiado grande. Usa una menor a 25 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return {data:canvas.toDataURL('image/jpeg',0.72),width:canvas.width,height:canvas.height};}
async function action(el){switch(el.dataset.action){case 'nav':closeModal();navTo(el.dataset.view);break;case 'start-route':startRoute();break;case 'shop':shopForm();break;case 'edit-shop':shopForm(db.shops.find(s=>s.id===el.dataset.id));break;case 'shop-detail':shopDetail(db.shops.find(s=>s.id===el.dataset.id));break;case 'visit':visitForm();break;case 'visit-here':visitForm();await captureLocation();break;case 'capture-location':await captureLocation();break;case 'clear-location':modalLocation=null;renderLocation();break;case 'visit-detail':visitDetail(db.visits.find(v=>v.id===el.dataset.id));break;case 'edit-visit':visitForm(db.visits.find(v=>v.id===el.dataset.id));break;case 'add-price':$('#price-lines').insertAdjacentHTML('beforeend',priceLine(0,db.shops.find(s=>s.id===$('#visit-shop').value)?.price??db.settings.price));drawIcons();break;case 'full-payment':$('[name="paid"]').value=(lineInputs().reduce((z,l)=>z+l.qty*l.price,0)/100).toFixed(2);break;case 'credit-payment':$('[name="paid"]').value='0.00';break;case 'remove-photo':modalPhotos.splice(Number(el.dataset.index),1);renderPhotos();break;case 'close-route':closeRoute();break;case 'reload':modal('Recargar el carro',`<form id="reload-form">${typeFields('Fundas agregadas','reload',{},productOptions())}${field('Nota','note','','text','maxlength="200"')}${formEnd('Guardar recarga')}</form>`);break;case 'receipt':receiptForm(el.dataset.id);break;case 'expense':expenseForm();break;case 'settings':settings();break;case 'modal-close':closeModal();break;case 'range-today':reports={start:today(),end:today()};render();break;case 'range-week':{const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));reports={start:d.toISOString().slice(0,10),end:today()};render();break;}case 'range-month':reports={start:today().slice(0,7)+'-01',end:today()};render();break;case 'excel':await excel();break;case 'backup':backup();break;case 'restore':$('#restore-input').click();break;case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;closeModal();render();}break;case 'delete-movement':{const type=el.dataset.type;const movement=(type==='receipt'?db.receipts:db.expenses).find(x=>x.id===el.dataset.id);if(db.routes.find(r=>r.id===movement.routeId)?.closed)throw Error('No puedes anular movimientos de una ruta cerrada.');modal('Anular movimiento',`<p>Se anulará ${type==='receipt'?'el cobro':'el gasto'} de <strong>${money(movement.amount)}</strong>. ${type==='receipt'?'Las entregas volverán a tener ese saldo pendiente.':''}</p><div class="form-actions">${btn('Conservar','modal-close','quiet')}${btn('Anular movimiento','confirm-delete','danger',`data-type="${type}" data-id="${movement.id}"`)}</div>`);break;}case 'confirm-delete':await commit(next=>{const k=el.dataset.type==='receipt'?'receipts':'expenses';const m=next[k].find(x=>x.id===el.dataset.id);if(next.routes.find(r=>r.id===m.routeId)?.closed)throw Error('La ruta está cerrada.');next[k]=next[k].filter(x=>x.id!==m.id);});closeModal();render();toast('Movimiento anulado.');break;case 'delete-route':deleteRoutePrompt(el.dataset.id);break;case 'confirm-delete-route':await commit(next=>deleteRoute(next,el.dataset.id));closeModal();navTo('route');toast('Ruta eliminada con sus visitas, cobros y gastos.');break;case 'route-detail':{const r=db.routes.find(r=>r.id===el.dataset.id),s=routeStats(db,r);modal('Resumen de ruta',`<p>${esc(dateLabel(r.date))}</p><div class="inventory-row"><span>Salida / recargas</span><strong>${r.initial} / ${s.reload}</strong></div><div class="inventory-row"><span>Vendidas / cortesías / cambios</span><strong>${s.sold} / ${s.gifts} / ${s.replacements}</strong></div><div class="inventory-row"><span>Regreso esperado / físico</span><strong>${s.expected} / ${r.closed?r.actual:'—'}</strong></div><div class="inventory-row"><span>Ventas</span><strong>${money(s.sales)}</strong></div><div class="inventory-row"><span>Efectivo esperado / físico</span><strong>${money(s.cashExpected)} / ${r.closed?money(r.actualCash):'—'}</strong></div><div class="button-row">${btn('Ver Excel de esta fecha','route-report','primary',`data-date="${r.date}"`)}${btn(`${icon('trash-2')} Eliminar ruta`,'delete-route','outline',`data-id="${r.id}"`)}</div>`);break;}case 'route-report':reports={start:el.dataset.date,end:el.dataset.date};closeModal();navTo('reports');break;case 'confirm-restore':{const restored=window.pendingRestore;if(!restored)throw Error('Selecciona una copia.');await commit(next=>{const revision=next.revision;Object.keys(next).forEach(k=>delete next[k]);Object.assign(next,restored,{revision});});window.pendingRestore=null;closeModal();render();toast('Copia restaurada.');break;}}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{await action(el);}catch(err){toast(err.message,true);}}if(e.target.closest('.remove-price')){if($$('#price-lines .price-line').length>1)e.target.closest('.price-line').remove();else toast('Conserva una línea de precio; puedes poner cantidad 0.');updateTotal();}if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('input',e=>{if(e.target.closest('#visit-form'))updateTotal();if(e.target.id==='shop-search'){const pos=e.target.selectionStart;shopQuery=e.target.value;render();$('#shop-search').focus();$('#shop-search').setSelectionRange(pos,pos);}if(e.target.closest('#close-form')){try{const f=$('#close-form'),s=routeStats(db,active());const values=Object.fromEntries(new FormData(f));const pan=typeTotal(readTypes(values,'actual',productOptions()))-s.expected;const cash=cents(f.elements.actualCash.value)-s.cashExpected;$('#close-preview').textContent=`Diferencia en pan: ${pan===null?'ingresa el conteo':pan+' fundas'}. Diferencia en efectivo: ${money(cash)}.`;}catch{}}});
document.addEventListener('change',async e=>{try{if(e.target.id==='visit-shop'){const s=db.shops.find(s=>s.id===e.target.value);if(s){$('#price-lines [name="price"]').value=(s.price/100).toFixed(2);updateTotal();}}if(e.target.id==='map-date'){mapDate=e.target.value;render();}if(e.target.closest('#visit-form'))updateTotal();if(['report-start','report-end'].includes(e.target.id)){reports[e.target.id==='report-start'?'start':'end']=e.target.value;render();}if(['camera-input','gallery-input'].includes(e.target.id)){const files=[...e.target.files];if(files.length+modalPhotos.length>6)throw Error('Puedes guardar hasta 6 fotos por visita.');const submit=$('#visit-form [type="submit"]');submit.disabled=true;try{for(const f of files)modalPhotos.push(await compress(f));renderPhotos();}finally{submit.disabled=false;e.target.value='';}}if(e.target.id==='restore-input'){const f=e.target.files[0];if(!f)return;if(f.size>100*1024*1024)throw Error('La copia supera 100 MB.');window.pendingRestore=validateDB(JSON.parse(await f.text()));modal('Restaurar copia',`<p>La copia contiene <strong>${window.pendingRestore.routes.length} rutas</strong>, <strong>${window.pendingRestore.visits.length} visitas</strong> y <strong>${window.pendingRestore.shops.length} tiendas</strong>.</p><div class="notice">Reemplazará los datos actuales de este celular. Descarga una copia actual antes de continuar.</div><div class="form-actions">${btn('Descargar copia actual','backup','outline')}${btn('Cancelar','modal-close','quiet')}${btn('Reemplazar con esta copia','confirm-restore','danger')}</div>`);}}catch(err){toast(err.message,true);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(!form.id)return;const f=Object.fromEntries(new FormData(form));const button=form.querySelector('[type="submit"]');const error=form.querySelector('.form-error');error.textContent='';button.disabled=true;try{switch(form.id){case 'start-form':{if(active())throw Error('Ya existe una ruta abierta.');const date=f.date;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today())throw Error('Elige hoy o una fecha anterior.');if(db.routes.some(x=>x.date>date))throw Error('La fecha no puede ser anterior a tus rutas ya registradas.');const route={id:id(),date,initial:typeTotal(readTypes(f,'initial',PRODUCTS)),initialByType:readTypes(f,'initial',PRODUCTS),openingCash:cents(f.openingCash),cost:db.settings.cost,createdAt:now(),closed:false,reloads:[]};await commit(next=>next.routes.push(route));view='route';break;}case 'shop-form':{const shop={...db.shops.find(s=>s.id===form.dataset.id),id:form.dataset.id||id(),name:f.name.trim(),address:f.address.trim(),phone:f.phone.trim(),notes:f.notes.trim(),price:cents(f.price)};if(!shop.name)throw Error('Ingresa el nombre de la tienda.');if(!shop.price)throw Error('El precio habitual debe ser mayor que cero.');await commit(next=>{const idx=next.shops.findIndex(s=>s.id===shop.id);if(idx>=0)next.shops[idx]=shop;else next.shops.push(shop);});break;}case 'visit-form':{const r=active(),old=db.visits.find(v=>v.id===form.dataset.id);f.shopId=old?.shopId||f.shopId;let shop=db.shops.find(s=>s.id===f.shopId),newShop=null;if(!shop){if(!modalLocation)throw Error('Usa tu ubicación o selecciona una tienda guardada.');newShop={id:id(),name:f.pointName?.trim()||`Punto de entrega ${String(db.shops.length+1).padStart(2,'0')}`,address:'Punto por ubicación',phone:'',notes:'',price:db.settings.price,location:structuredClone(modalLocation)};shop=newShop;f.shopId=shop.id;}const visit={id:old?.id||id(),routeId:r.id,date:r.date,createdAt:old?.createdAt||now(),shopId:f.shopId,shopName:old?.shopName||shop?.name,shopAddress:old?.shopAddress||shop?.address,lines:lineInputs(),...Object.fromEntries(['gifts','replacements','expired'].flatMap(k=>{const m=readTypes(f,k,productOptions());return [[k,typeTotal(m)],[k+'ByType',m]];})),location:structuredClone(modalLocation),expiry:f.expiry,notes:f.notes.trim(),photos:structuredClone(modalPhotos),updatedAt:now()};validateVisit(newShop?{...db,shops:[...db.shops,newShop]}:db,visit,old?.id);if(visit.lines.some(l=>l.qty&&l.price!==(shop?.price??db.settings.price)&&!l.reason))throw Error('Indica el motivo de las líneas con precio distinto al habitual de la tienda.');const amount=old?0:cents(f.paid,'Cobrado');if(amount>sale(visit))throw Error('El cobro supera la venta. Para deudas anteriores usa Finanzas.');await commit(next=>{if(newShop)next.shops.push(newShop);validateVisit(next,visit,old?.id);const idx=next.visits.findIndex(v=>v.id===visit.id);if(idx>=0)next.visits[idx]=visit;else next.visits.push(visit);if(amount)next.receipts.push({id:id(),routeId:r.id,date:r.date,createdAt:now(),shopId:visit.shopId,method:f.method,amount,note:'Cobro de la visita',allocations:[{visitId:visit.id,amount}]});});break;}case 'reload-form':{const r=active();if(!r)throw Error('La ruta está cerrada.');const byType=readTypes(f,'reload',productOptions()),qty=typeTotal(byType);if(!qty)throw Error('Ingresa al menos una funda.');await commit(next=>next.routes.find(x=>x.id===r.id).reloads.push({qty,byType,note:f.note.trim(),createdAt:now()}));break;}case 'close-form':{const r=active();if(!r)throw Error('La ruta ya está cerrada.');const actualByType=readTypes(f,'actual',productOptions()),actualExpiredByType=readTypes(f,'actualExpired',productOptions()),actual=typeTotal(actualByType),actualExpired=typeTotal(actualExpiredByType),actualCash=cents(f.actualCash);const s=routeStats(db,r);if((actual!==s.expected||actualCash!==s.cashExpected||actualExpired!==s.expired||Object.entries(routeTypes(db,r)).some(([k,v])=>(actualByType[k]||0)!==v.expected||(actualExpiredByType[k]||0)!==v.expired))&&!f.note.trim())throw Error('Escribe una nota para explicar la diferencia de pan, efectivo o caducadas.');await commit(next=>Object.assign(next.routes.find(x=>x.id===r.id),{closed:true,actual,actualByType,actualExpired,actualExpiredByType,actualCash,note:f.note.trim(),closedAt:now()}));view='route';break;}case 'receipt-form':{const r=active();if(!r)throw Error('Necesitas una ruta abierta.');const amount=cents(f.amount),allocations=allocate(db,f.shopId,amount);await commit(next=>next.receipts.push({id:id(),routeId:r.id,date:r.date,createdAt:now(),shopId:f.shopId,method:f.method,amount,allocations,note:f.note.trim()}));break;}case 'expense-form':{const r=active();if(!r)throw Error('Necesitas una ruta abierta.');const amount=cents(f.amount);if(!amount||!f.description.trim())throw Error('Ingresa un detalle y un gasto mayor que cero.');await commit(next=>next.expenses.push({id:id(),routeId:r.id,date:r.date,createdAt:now(),description:f.description.trim(),amount,method:f.method}));break;}case 'settings-form':{const price=cents(f.price);if(!price||!f.name.trim())throw Error('Ingresa un nombre y un precio mayor que cero.');const cost=f.cost===''?null:cents(f.cost,'Costo');await commit(next=>next.settings={name:f.name.trim(),price,cost});break;}default:return;}closeModal();render();toast(form.id==='close-form'?'Ruta cerrada. Ya puedes descargar el Excel.':'Registro guardado.');}catch(err){error.textContent=err.message;button.disabled=false;}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;render();});window.addEventListener('online',render);window.addEventListener('offline',render);
async function boot(){try{conn=await new Promise((resolve,reject)=>{const request=indexedDB.open('quinua-ruta:'+new URL('./',location.href).pathname,1);request.onupgradeneeded=()=>request.result.createObjectStore('data');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});db=await readData();render();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('No se preparó el modo sin conexión. Abre la app con señal y vuelve a intentarlo.',true));const context=document.modelContext;if(context?.registerTool){Promise.resolve(context.registerTool({name:'read_route_summary',title:'Consultar ruta de quinua',description:'Devuelve el inventario y dinero de la ruta activa o última ruta, sin modificar registros.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('No se admiten parámetros.');const r=lastRoute();return r?{date:r.date,closed:r.closed,...routeStats(db,r),visits:routeStats(db,r).visits.length}:{status:'no_route'};}})).catch(()=>{});}}catch(e){$('#app').innerHTML=`<div class="startup-error"><h1>No pudimos abrir tus registros</h1><p>Verifica que el almacenamiento del navegador esté habilitado. Usa Chrome y evita el modo incógnito.</p><button onclick="location.reload()">Volver a intentar</button></div>`;}}
boot();
